	},
	heroSection: {
		alignItems: "center",
		justifyContent: "center",
		gap: Spacing.three,
		flex: 1,
	},
	title: {
		textAlign: "center",
	},
	subtitle: {
		textAlign: "center",
	},
	email: {
		textAlign: "center",
		opacity: 0.7,
	},
});

